print("Detailed analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"  {inp} -> {outp}")
    if inp != outp:
        print(f"    Difference: {len(outp)} chars vs {len(inp)} chars")
        # Show positions where they differ
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))
        if len(outp) > len(inp):
            for j in range(len(inp), len(outp)):
                diff_positions.append((j, '_', outp[j]))
        elif len(inp) > len(outp):
            for j in range(len(outp), len(inp)):
                diff_positions.append((j, inp[j], '_'))
        if diff_positions:
            print(f"    Changes at positions: {diff_positions}")
    else:
        print("    No change")
